INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 8, 'theory', 'Quiz: synchronization and locks');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 0, 'Why is an unprotected counter++ dangerous on multiple cores?', '["It is three steps: read, add, write; two cores can read the same value and lose an update", "The processor cannot add numbers in parallel", "The variable can turn into a string", "The kernel forbids such a write"]', 0, 'A lost update shows up rarely and depends on timing, so shared data must always be protected.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 1, 'Why can''t you sleep inside a spinlock?', '["A spinlock does not support sleeping at the hardware level", "Sleeping releases the spinlock", "The holder falls asleep while the other cores spin in a loop for nothing; a deadlock is also possible", "This restriction applies only to 32-bit systems"]', 2, 'A spinlock is for short sections. For long ones, or ones that sleep, use a mutex.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 2, 'Both an interrupt handler and process code touch the data. Which lock should the process code take?', '["An ordinary mutex", "A spinlock that disables interrupts on its own core (irqsave)", "None: the interrupt is short anyway", "A read-write lock (rwsem)"]', 1, 'Otherwise the handler interrupts the holder on the same core and hangs, waiting for a lock that nobody will ever release.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 3, 'When does RCU free the old version of a structure?', '["Right after publishing the new pointer", "At the next reboot", "When the reference count reaches 100", "After a grace period, once all readers that could see it have left their critical sections"]', 3, 'Readers take no locks, so the writer waits until every core passes a safe point, and only then frees the old version.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 4, 'What does lockdep do?', '["Automatically releases stuck locks", "Speeds up taking locks", "Remembers the locking order and warns about a possible cycle before a real hang", "Disables interrupts when a mutex is taken"]', 2, 'It is enabled in debug builds. One wrong locking order in tests, and the kernel log shows the chain.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 5, 'Why must you not hold a spinlock while calling a function that may sleep?', '["Other processors will spin uselessly while waiting, and the owner may not get the processor back any time soon", "Because a spinlock is released automatically on sleep", "Because a sleeping function always fails", "Because the kernel forbids calling functions inside a lock"]', 0, 'A spinlock is meant for very short sections. Whoever needs to sleep takes a mutex.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 6, 'How does RCU let readers avoid blocking altogether?', '["Readers take a fast read spinlock", "Writers wait until there are no readers left at all", "The data is protected by disabling interrupts", "The writer makes a new copy and swaps the pointer, and frees the old one only after all current readers have finished"]', 3, 'Readers see either the old or the new version in full. The price is deferred freeing, but reading stays cheap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 8, 7, 'What is the simplest way to avoid a deadlock between two mutexes?', '["Take the mutexes faster than the other threads", "Always take them in the same order throughout the code", "Hold both for as long as possible", "Increase the number of threads"]', 1, 'Deadlock happens when one thread takes A then B and another takes B then A. A single order breaks the wait cycle.');
